#!/usr/bin/env python3
"""Reap only descendants of this diagnostic runner; never alter test outcomes."""
import ctypes
import os
import signal
import sys

if len(sys.argv) < 2:
    raise SystemExit('usage: mdkg-cloud-subreaper.py COMMAND [ARG ...]')
libc = ctypes.CDLL(None, use_errno=True)
if libc.prctl(36, 1, 0, 0, 0) != 0:  # Linux PR_SET_CHILD_SUBREAPER
    raise OSError(ctypes.get_errno(), 'PR_SET_CHILD_SUBREAPER failed')
main_pid = os.fork()
if main_pid == 0:
    os.execvp(sys.argv[1], sys.argv[1:])

def forward(signum, _frame):
    try:
        os.kill(main_pid, signum)
    except ProcessLookupError:
        pass

signal.signal(signal.SIGINT, forward)
signal.signal(signal.SIGTERM, forward)
main_status = None
reaped = 0
while True:
    try:
        pid, status = os.waitpid(-1, 0)
    except InterruptedError:
        continue
    except ChildProcessError:
        break
    if pid == main_pid:
        main_status = os.waitstatus_to_exitcode(status)
    else:
        reaped += 1
print(f'cloud runner: reaped {reaped} owned descendant(s); command exit {main_status}', file=sys.stderr)
if main_status is None:
    raise SystemExit('main command exit status was not observed')
raise SystemExit(main_status if main_status >= 0 else 128 - main_status)

