const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const cases = [];
for (const variant of ['baseline', 'plan']) {
  const root = `/workspace/mdkg-cloud-${variant}`;
  const { releaseEnvironment } = require(path.join(root, 'scripts/release-ladder.js'));
  for (const place of ['original', 'clean']) {
    const receipts = place === 'original'
      ? `/tmp/mdkg-cloud-effective-${variant}`
      : `/dev/shm/mdkg-cloud-fixtures/effective-${variant}`;
    const env = releaseEnvironment(receipts, {
      npm: '/opt/codex/runtimes/codex-primary-runtime/dependencies/node/lib/node_modules/npm/bin/npm-cli.js',
      npx: '/opt/codex/runtimes/codex-primary-runtime/dependencies/node/lib/node_modules/npm/bin/npx-cli.js',
    });
    const result = spawnSync(process.execPath, [
      '--test', '--test-reporter=tap',
      '--test-name-pattern=validate and index accept valid Agent workflow file fixtures',
      'dist/tests/commands/agent_file_types.test.js',
    ], { cwd: root, env, encoding: 'utf8' });
    const expected = place === 'original' ? 1 : 0;
    fs.writeFileSync(`/tmp/mdkg-cloud-effective-${variant}-${place}.log`, result.stdout + result.stderr);
    cases.push({ variant, place, effective_tmpdir: env.TMPDIR, exit_code: result.status,
      expected_exit_code: expected, result: result.status === expected ? 'passed-control' : 'unexpected',
      error: place === 'original' ? 'Git rev-parse observation failed; no successful observation emitted' : null });
  }
}
fs.writeFileSync('/tmp/mdkg-cloud-effective-temp-results.json', JSON.stringify(cases, null, 2) + '\n');
console.log(JSON.stringify(cases, null, 2));
process.exitCode = cases.every(c => c.result === 'passed-control') ? 0 : 1;
